package de.ostms.lc.lc.domain;
import jakarta.persistence.*;import java.math.BigDecimal;import java.time.*;import java.util.*;
@Entity @Table(name="lc_amendment") public class Amendment extends de.ostms.lc.tenant.domain.TenantOwnedEntity { @Column(nullable=false,length=12) private String status="PENDING"; private LocalDateTime decidedAt; @Column(length=100) private String decidedBy; @Column(length=500) private String decisionComment; @Column(columnDefinition="text") private String otherChanges;
 public String getStatus(){return status;} public void setStatus(String v){status=v;} public LocalDateTime getDecidedAt(){return decidedAt;} public String getDecidedBy(){return decidedBy;} public String getDecisionComment(){return decisionComment;}
 public String getOtherChanges(){return otherChanges;} public void setOtherChanges(String v){otherChanges=v;}
 public boolean isPending(){return "PENDING".equals(status);} public boolean isAccepted(){return "ACCEPTED".equals(status);}
 public void decide(String newStatus,String user,String comment){status=newStatus;decidedAt=LocalDateTime.now();decidedBy=user;decisionComment=comment==null||comment.isBlank()?null:(comment.trim().length()>500?comment.trim().substring(0,500):comment.trim());}
 @Column(columnDefinition="text") private String beforeState; @Column(columnDefinition="text") private String afterState; public String getBeforeState(){return beforeState;} public void setBeforeState(String value){beforeState=value;} public String getAfterState(){return afterState;} public void setAfterState(String value){afterState=value;} @Id @GeneratedValue(strategy=GenerationType.UUID)private UUID id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="lc_id")@com.fasterxml.jackson.annotation.JsonIgnore private LetterOfCredit letterOfCredit;private String amendmentNumber;private LocalDate amendmentDate;private BigDecimal amountIncrease;private BigDecimal amountDecrease;private LocalDate newExpiryDate;private String newExpiryPlace;private LocalDate newLatestShipmentDate;@Column(length=4000)private String changedDocuments;@Column(columnDefinition="text")private String changedGoods;@Column(columnDefinition="text")private String changedConditions;@Column(columnDefinition="text")private String rawMessage;private LocalDateTime importedAt=LocalDateTime.now();public UUID getId(){return id;}public LetterOfCredit getLetterOfCredit(){return letterOfCredit;}public void setLetterOfCredit(LetterOfCredit v){letterOfCredit=v;}public String getAmendmentNumber(){return amendmentNumber;}public void setAmendmentNumber(String v){amendmentNumber=v;}public LocalDate getAmendmentDate(){return amendmentDate;}public void setAmendmentDate(LocalDate v){amendmentDate=v;}public BigDecimal getAmountIncrease(){return amountIncrease;}public void setAmountIncrease(BigDecimal v){amountIncrease=v;}public BigDecimal getAmountDecrease(){return amountDecrease;}public void setAmountDecrease(BigDecimal v){amountDecrease=v;}public LocalDate getNewExpiryDate(){return newExpiryDate;}public void setNewExpiryDate(LocalDate v){newExpiryDate=v;}public String getNewExpiryPlace(){return newExpiryPlace;}public void setNewExpiryPlace(String v){newExpiryPlace=v;}public LocalDate getNewLatestShipmentDate(){return newLatestShipmentDate;}public void setNewLatestShipmentDate(LocalDate v){newLatestShipmentDate=v;}public String getChangedDocuments(){return changedDocuments;}public void setChangedDocuments(String v){changedDocuments=v;}public String getChangedGoods(){return changedGoods;}public void setChangedGoods(String v){changedGoods=v;}public String getChangedConditions(){return changedConditions;}public void setChangedConditions(String v){changedConditions=v;}public String getRawMessage(){return rawMessage;}public void setRawMessage(String v){rawMessage=v;}public LocalDateTime getImportedAt(){return importedAt;}}
